def predict(board, action):
    mouse_row, mouse_col = action[1], action[2]
    mouse_char = board[mouse_row][mouse_col]

    if mouse_char == 'B':
        # Move B horizontally to the left
        for i in range(mouse_col-1, -1, -1):
            if board[mouse_row][i] != 'W':
                board[mouse_row][i] = 'B'
                board[mouse_row][i+1] = 'S'
    elif mouse_char == 'G':
        # Move G horizontally to the left
        for i in range(mouse_col-1, -1, -1):
            if board[mouse_row][i] != 'W':
                board[mouse_row][i] = 'G'
                board[mouse_row][i+1] = 'S'
    elif mouse_char == 'N':
        # Move N horizontally to the left
        for i in range(mouse_col-1, -1, -1):
            if board[mouse_row][i] != 'W':
                board[mouse_row][i] = 'N'
                board[mouse_row][i+1] = 'S'
    elif mouse_char == 'W':
        # Place 'p' at the mouse position
        board[mouse_row][mouse_col] = 'p'

    return board
